type Env = { ASSETS: Fetcher; ARTIFACTS: R2Bucket }

const DATA = "/artifacts/data/artifacts/"
const API = "/artifacts/api/annotations/"

export default {
  async fetch(request: Request, env: Env): Promise<Response> {
    const url = new URL(request.url)
    const pathname = decodeURIComponent(url.pathname)

    // Data routes: read from R2
    if (pathname.startsWith(DATA)) {
      const key = pathname.slice(DATA.length)
      const object = await env.ARTIFACTS.get(key)
      if (!object) return new Response("Not found", { status: 404 })
      return new Response(object.body, {
        headers: {
          "Content-Type": object.httpMetadata?.contentType ?? "application/json",
          "Cache-Control": "public, max-age=60, s-maxage=300",
        },
      })
    }

    // Annotation API: defer to later; return 501 for now
    if (pathname.startsWith(API)) {
      return new Response("Remote annotations not implemented", { status: 501 })
    }

    // Everything else: static export, with live shell fallback
    return env.ASSETS.fetch(new Request(new URL(shellPath(pathname), url.origin), request))
  },
}

function shellPath(pathname: string): string {
  const stripped = pathname.startsWith("/artifacts")
    ? pathname.slice("/artifacts".length) || "/"
    : pathname
  const parts = stripped.split("/").filter(Boolean)
  if (parts.length === 2) return "/shell-artifact/"
  if (parts.length === 1 && !["_next", "data", "api"].includes(parts[0])) return "/shell-project/"
  return stripped
}
